const registries = new WeakMap()

export function pipeTo(readable, destination, options) {
  readable.pipe(destination, options)
  let set = registries.get(readable)
  if (!set) { set = new Set(); registries.set(readable, set) }
  set.add(destination)
  const cleanup = () => set.delete(destination)
  destination.once("unpipe", cleanup)
  destination.once("close", cleanup)
  destination.once("finish", cleanup)
  return destination
}

