{
  "name": "unpipe-server",
  "version": "1.0.0",
  "description": "Node.js HTTP server that reliably unpipes a readable stream from all of its destinations",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

const tracked = new WeakMap()

function destinationsFor(readable) {
  let destinations = tracked.get(readable)
  if (!destinations) {
    destinations = new Set()
    tracked.set(readable, destinations)
  }
  return destinations
}

export function pipe(readable, destination, options) {
  readable.pipe(destination, options)

  const destinations = destinationsFor(readable)
  destinations.add(destination)

  const forget = () => destinations.delete(destination)
  destination.once("unpipe", forget)
  destination.once("close", forget)
  destination.once("finish", forget)

  return destination
}

export function unpipeAll(readable) {
  if (!readable || typeof readable.unpipe !== "function") {
    throw new TypeError("unpipeAll expects a readable stream")
  }

  const destinations = tracked.get(readable)
  if (destinations) {
    for (const destination of [...destinations]) {
      readable.unpipe(destination)
    }
    destinations.clear()
  }

  readable.unpipe()
  return readable
}

export function destinationsOf(readable) {
  const destinations = tracked.get(readable)
  return destinations ? [...destinations] : []
}

import http from "node:http"
import { PassThrough, Readable } from "node:stream"
import { pipe, unpipeAll } from "./unpipe.js"

const PORT = Number(process.env.PORT ?? 3000)

function createSource() {
  let index = 0
  return new Readable({
    read() {
      index += 1
      if (index <= 5) {
        this.push(`chunk ${index}\n`)
      } else {
        this.push(null)
      }
    },
  })
}

const server = http.createServer((req, res) => {
  if (req.url === "/health") {
    res.writeHead(200, { "content-type": "application/json" })
    res.end(JSON.stringify({ status: "ok" }))
    return
  }

  const source = createSource()

  const audit = new PassThrough()
  audit.on("data", (chunk) => process.stdout.write(`[audit] ${chunk}`))

  pipe(source, res)
  pipe(source, audit)

  res.on("close", () => {
    unpipeAll(source)
    audit.destroy()
  })
})

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`)
})

export { server, createSource }

import test from "node:test"
import assert from "node:assert/strict"
import { Readable, Writable } from "node:stream"
import { pipe, unpipeAll, destinationsOf } from "../src/unpipe.js"

function source() {
  let index = 0
  return new Readable({
    read() {
      index += 1
      if (index <= 3) {
        this.push(`chunk ${index}\n`)
      } else {
        this.push(null)
      }
    },
  })
}

function collector() {
  const chunks = []
  const writable = new Writable({
    write(chunk, _encoding, callback) {
      chunks.push(chunk.toString())
      callback()
    },
  })
  writable.chunks = chunks
  return writable
}

test("unpipeAll detaches every destination", () => {
  const readable = source()
  const a = collector()
  const b = collector()

  pipe(readable, a)
  pipe(readable, b)

  assert.equal(destinationsOf(readable).length, 2)

  unpipeAll(readable)

  assert.deepEqual(destinationsOf(readable), [])
  assert.equal(readable._readableState.pipes.length, 0)
})

test("no data reaches destinations unpiped before flow", async () => {
  const readable = source()
  const a = collector()
  const b = collector()

  pipe(readable, a)
  pipe(readable, b)
  unpipeAll(readable)

  readable.resume()
  await new Promise((resolve) => readable.on("end", resolve))

  assert.deepEqual(a.chunks, [])
  assert.deepEqual(b.chunks, [])
})

test("unpipeAll is idempotent", () => {
  const readable = source()
  pipe(readable, collector())

  assert.doesNotThrow(() => {
    unpipeAll(readable)
    unpipeAll(readable)
  })
  assert.deepEqual(destinationsOf(readable), [])
})
